1	"use client";
2	
3	import Link from "next/link";
4	import { usePathname } from "next/navigation";
5	import { useEffect, useState } from "react";
6	import { useTheme } from "next-themes";
7	import { cn } from "@repo/ui/lib/utils";
8	import {
9	  ChevronDown, ChevronRight, LayoutDashboard, AlertTriangle, Building2,
10	  Users, Wrench, FileText, MessageSquareText, Sparkles, Home,
11	  PanelLeftClose, PanelLeftOpen, Sun, Moon, RotateCcw, Loader2, Zap,
12	} from "lucide-react";
13	import { api } from "@/lib/api";
14	import { subscribe } from "@/lib/bus";
15	import { useToastSafe } from "@/components/toaster";
16	import { useAutoSolve } from "@/lib/auto-solve-context";
17	import type { Property } from "@/lib/types";
18	
19	const PROP_TABS = [
20	  ["tickets",  "Tickets"],
21	  ["units",    "Units & Owners"],
22	  ["context",  "Context"],
23	  ["editor",   "Editor"],
24	  ["versions", "Versions"],
25	  ["sources",  "Sources"],
26	  ["policies", "Policies"],
27	  ["calls",    "Calls"],
28	] as const;
29	
30	export function Sidebar() {
31	  const pathname = usePathname();
32	  const [collapsed, setCollapsed] = useState(false);
33	  const [openProps, setOpenProps] = useState<Record<string, boolean>>({ p1: true });
34	  const [properties, setProperties] = useState<Property[]>([]);
35	  const { theme, setTheme } = useTheme();
36	  const [mounted, setMounted] = useState(false);
37	  useEffect(() => setMounted(true), []);
38	
39	  // Demo reset state
40	  const [showResetConfirm, setShowResetConfirm] = useState(false);
41	  const [resetting, setResetting] = useState(false);
42	  const toast = useToastSafe();
43	
44	  // Auto-Solve toggle (Sprint 3)
45	  const { autoSolve, queueStatus, isToggling, enable, disable } = useAutoSolve();
46	  const [showAutoSolveConfirm, setShowAutoSolveConfirm] = useState(false);
47	
48	  useEffect(() => {
49	    let cancelled = false;
50	    const refresh = () =>
51	      api.properties.list()
52	        .then((list) => { if (!cancelled) setProperties(list); })
53	        .catch(() => { /* silently leave list empty */ });
54	    refresh();
55	    const unsub = subscribe((event) => {
56	      if (event.kind === "context-bumped" || event.kind === "ticket-changed") refresh();
57	    });
58	    return () => { cancelled = true; unsub(); };
59	  }, []);
60	
61	  const activePropId = pathname.match(/^\/property\/([^/]+)/)?.[1] ?? null;
62	  const activeProp = activePropId ? properties.find((p) => p.id === activePropId) ?? null : null;
63	
64	  async function handleAutoSolveToggle() {
65	    if (autoSolve) {
66	      try {
67	        await disable();
68	        toast.push({
69	          title: "Auto-Solve stopped",
70	          description: "The agent will finish the current ticket and then stop.",
71	          variant: "default",
72	        });
73	      } catch (err) {
74	        toast.push({
75	          title: "Failed to stop",
76	          description: err instanceof Error ? err.message : "Unknown error",
77	          variant: "destructive",
78	        });
79	      }
80	    } else {
81	      setShowAutoSolveConfirm(true);
82	    }
83	  }
84	
85	  async function handleAutoSolveConfirm() {
86	    setShowAutoSolveConfirm(false);
87	    try {
88	      await enable();
89	      toast.push({
90	        title: "Auto-Solve activated",
91	        description: "Hermes is now processing tickets autonomously.",
92	        variant: "success",
93	      });
94	    } catch (err) {
95	      toast.push({
96	        title: "Failed to start",
97	        description: err instanceof Error ? err.message : "Unknown error",
98	        variant: "destructive",
99	      });
100	    }
101	  }
102	
103	  async function handleReset() {
104	    setShowResetConfirm(false);
105	    setResetting(true);
106	    try {
107	      await api.dev.reset();
108	      toast.push({
109	        title: "Demo zurückgesetzt",
110	        description: "Alle Tickets und Daten wurden auf den Demo-Ausgangszustand zurückgesetzt.",
111	        variant: "success",
112	      });
113	      // Hard-redirect to overview so all client state (sidebar counts,
114	      // cached queries) is fully wiped — avoids the router.refresh() race
115	      // condition where refresh fires against the current route, not /overview.
116	      window.location.href = "/overview";
117	    } catch (err) {
118	      toast.push({
119	        title: "Reset fehlgeschlagen",
120	        description: err instanceof Error ? err.message : "Unbekannter Fehler beim Zurücksetzen.",
121	        variant: "destructive",
122	      });
123	    } finally {
124	      setResetting(false);
125	    }
126	  }
127	
128	  return (
129	    <>
130	      <aside
131	        className={cn(
132	          "flex h-full shrink-0 flex-col border-r bg-background transition-all duration-200",
133	          collapsed ? "w-14" : "w-64"
134	        )}
135	      >
136	        {/* Header */}
137	        <div className="flex h-14 items-center justify-between border-b px-3">
138	          {!collapsed && (
139	            <div className="flex items-center gap-2 min-w-0">
140	              <div className="grid h-7 w-7 shrink-0 place-items-center rounded-md bg-foreground text-background">
141	                <Sparkles className="h-4 w-4" />
142	              </div>
143	              <div className="flex flex-col leading-tight min-w-0">
144	                <span className="text-sm font-semibold">Buena</span>
145	                <span className="text-[10px] uppercase tracking-wider text-muted-foreground">Context Engine</span>
146	              </div>
147	            </div>
148	          )}
149	          {collapsed && (
150	            <div className="mx-auto grid h-7 w-7 place-items-center rounded-md bg-foreground text-background">
151	              <Sparkles className="h-4 w-4" />
152	            </div>
153	          )}
154	          {!collapsed && (
155	            <button
156	              onClick={() => setCollapsed(true)}
157	              className="ml-2 rounded-md p-1 text-muted-foreground hover:bg-accent hover:text-foreground"
158	              title="Collapse sidebar"
159	            >
160	              <PanelLeftClose className="h-4 w-4" />
161	            </button>
162	          )}
163	        </div>
164	
165	        {/* Demo Mode Banner (visible when expanded) */}
166	        {!collapsed && (
167	          <div className="flex items-center gap-1.5 border-b bg-amber-500/10 px-3 py-1.5">
168	            <span className="h-1.5 w-1.5 shrink-0 rounded-full bg-amber-500 animate-pulse" />
169	            <span className="text-[10px] font-semibold uppercase tracking-wider text-amber-600 dark:text-amber-400">
170	              Demo Mode
171	            </span>
172	          </div>
173	        )}
174	
175	        {/* Expand button when collapsed */}
176	        {collapsed && (
177	          <button
178	            onClick={() => setCollapsed(false)}
179	            className="mx-auto mt-3 rounded-md p-1.5 text-muted-foreground hover:bg-accent hover:text-foreground"
180	            title="Expand sidebar"
181	          >
182	            <PanelLeftOpen className="h-4 w-4" />
183	          </button>
184	        )}
185	
186	        {/* Collapsed demo mode dot */}
187	        {collapsed && (
188	          <div
189	            className="mx-auto mt-1 h-1.5 w-1.5 rounded-full bg-amber-500"
190	            title="Demo Mode"
191	          />
192	        )}
193	
194	        {/* Nav */}
195	        <nav className={cn("flex-1 overflow-y-auto p-2 text-sm", collapsed && "overflow-hidden")}>
196	          {!collapsed ? (
197	            <>
198	              <Zone label="Work">
199	                <Item href="/overview"    icon={LayoutDashboard} active={pathname === "/overview"}>Overview</Item>
200	                <Item href="/escalations" icon={AlertTriangle}   active={pathname === "/escalations"}>Escalations</Item>
201	              </Zone>
202	
203	              <Zone label="Properties">
204	                {properties.map((p) => {
205	                  const open = openProps[p.id];
206	                  const inThisProp = pathname.startsWith(`/property/${p.id}`);
207	                  return (
208	                    <div key={p.id}>
209	                      <button
210	                        onClick={() => setOpenProps((s) => ({ ...s, [p.id]: !s[p.id] }))}
211	                        className={cn(
212	                          "flex w-full items-center justify-between gap-2 rounded-md px-2 py-1.5 hover:bg-accent",
213	                          inThisProp && "bg-accent"
214	                        )}
215	                      >
216	                        <span className="flex items-center gap-2 truncate text-sm">
217	                          <Home className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
218	                          <span className="truncate">{p.name}</span>
219	                        </span>
220	                        <span className="flex shrink-0 items-center gap-1.5">
221	                          {p.openTickets > 0 && (
222	                            <span className="rounded-full bg-amber-500/20 px-1.5 text-[10px] font-medium text-amber-600 dark:text-amber-400">
223	                              {p.openTickets}
224	                            </span>
225	                          )}
226	                          {open ? <ChevronDown className="h-3 w-3" /> : <ChevronRight className="h-3 w-3" />}
227	                        </span>
228	                      </button>
229	                      {open && (
230	                        <div className="ml-5 mt-0.5 border-l pl-2">
231	                          {PROP_TABS.map(([slug, label]) => {
232	                            const href = `/property/${p.id}/${slug}`;
233	                            return (
234	                              <Link
235	                                key={slug}
236	                                href={href}
237	                                className={cn(
238	                                  "block rounded-md px-2 py-1 text-[13px] text-muted-foreground hover:bg-accent hover:text-foreground",
239	                                  pathname === href && "bg-accent text-foreground font-medium"
240	                                )}
241	                              >
242	                                {label}
243	                              </Link>
244	                            );
245	                          })}
246	                        </div>
247	                      )}
248	                    </div>
249	                  );
250	                })}
251	              </Zone>
252	
253	              <Zone label="Knowledge">
254	                <Item href="/vendors"   icon={Wrench}    active={pathname.startsWith("/vendors") || pathname.startsWith("/vendor/")}>Vendors</Item>
255	                <Item href="/owners"    icon={Users}     active={pathname.startsWith("/owners") || pathname.startsWith("/owner/")}>Owners</Item>
256	                <Item href="/buildings" icon={Building2} active={pathname.startsWith("/buildings") || pathname.startsWith("/building/")}>Buildings</Item>
257	              </Zone>
258	
259	              <Zone label="Tools">
260	                <Item href="/extract" icon={FileText}          active={pathname === "/extract"}>PDF Extract</Item>
261	                <Item href="/chat"    icon={MessageSquareText} active={pathname === "/chat"}>Hermes Chat</Item>
262	              </Zone>
263	            </>
264	          ) : (
265	            /* Icon-only mode */
266	            <div className="mt-1 flex flex-col items-center gap-1">
267	              {[
268	                { href: "/overview",    icon: LayoutDashboard,  label: "Overview" },
269	                { href: "/escalations", icon: AlertTriangle,    label: "Escalations" },
270	                { href: "/vendors",     icon: Wrench,           label: "Vendors" },
271	                { href: "/owners",      icon: Users,            label: "Owners" },
272	                { href: "/buildings",   icon: Building2,        label: "Buildings" },
273	                { href: "/extract",     icon: FileText,         label: "PDF Extract" },
274	                { href: "/chat",        icon: MessageSquareText, label: "Hermes Chat" },
275	              ].map(({ href, icon: Icon, label }) => (
276	                <Link
277	                  key={href}
278	                  href={href}
279	                  title={label}
280	                  className={cn(
281	                    "rounded-md p-2 text-muted-foreground hover:bg-accent hover:text-foreground",
282	                    pathname.startsWith(href) && href !== "/" && "bg-accent text-foreground"
283	                  )}
284	                >
285	                  <Icon className="h-4 w-4" />
286	                </Link>
287	              ))}
288	            </div>
289	          )}
290	        </nav>
291	
292	        {/* Footer */}
293	        <div className={cn("border-t p-3", collapsed && "flex flex-col items-center gap-2 px-0")}>
294	          {/* Theme toggle */}
295	          <button
296	            onClick={() => setTheme(theme === "dark" ? "light" : "dark")}
297	            className="flex items-center gap-2 rounded-md p-1.5 text-muted-foreground hover:bg-accent hover:text-foreground"
298	            title="Toggle theme"
299	            suppressHydrationWarning
300	          >
301	            <span suppressHydrationWarning className="inline-flex h-3.5 w-3.5 items-center justify-center">
302	              {mounted ? (theme === "dark" ? <Sun className="h-3.5 w-3.5" /> : <Moon className="h-3.5 w-3.5" />) : null}
303	            </span>
304	            {!collapsed && <span className="text-[11px]">Toggle theme</span>}
305	          </button>
306	
307	          {/* Auto-Solve Toggle (Sprint 3) */}
308	          <button
309	            onClick={handleAutoSolveToggle}
310	            disabled={isToggling}
311	            className={cn(
312	              "flex items-center gap-2 rounded-md p-1.5 transition-colors",
313	              autoSolve
314	                ? "bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 hover:bg-emerald-500/25"
315	                : "text-muted-foreground hover:bg-accent hover:text-foreground",
316	              isToggling && "opacity-60 cursor-not-allowed",
317	              collapsed && "justify-center"
318	            )}
319	            title={autoSolve ? "Auto-Solve ON — click to stop" : "Enable Agent Auto-Solve"}
320	          >
321	            {isToggling ? (
322	              <Loader2 className="h-3.5 w-3.5 animate-spin" />
323	            ) : (
324	              <Zap className={cn("h-3.5 w-3.5 shrink-0", autoSolve && "animate-pulse")} />
325	            )}
326	            {!collapsed && (
327	              <span className="text-[11px] font-medium">
328	                {autoSolve
329	                  ? `Auto-Solve ON${queueStatus.remainingCount > 0 ? ` (${queueStatus.remainingCount} left)` : ""}`
330	                  : "Agent Auto-Solve"}
331	              </span>
332	            )}
333	          </button>
334	
335	          {/* Reset Demo button */}
336	          <button
337	            onClick={() => setShowResetConfirm(true)}
338	            disabled={resetting}
339	            className={cn(
340	              "flex items-center gap-2 rounded-md p-1.5 text-muted-foreground hover:bg-destructive/10 hover:text-destructive transition-colors",
341	              resetting && "opacity-60 cursor-not-allowed",
342	              collapsed && "justify-center"
343	            )}
344	            title="Reset Demo"
345	          >
346	            {resetting ? (
347	              <Loader2 className="h-3.5 w-3.5 animate-spin" />
348	            ) : (
349	              <RotateCcw className="h-3.5 w-3.5" />
350	            )}
351	            {!collapsed && (
352	              <span className="text-[11px]">
353	                {resetting ? "Resetting…" : "Reset Demo"}
354	              </span>
355	            )}
356	          </button>
357	
358	          {!collapsed && (
359	            <div className="mt-2 text-[11px] text-muted-foreground">
360	              {activeProp ? (
361	                <div className="flex items-center justify-between" title={activeProp.name}>
362	                  <span className="truncate">{activeProp.name} · context.md</span>
363	                  <span className="font-mono tabular-nums text-foreground/80">v{activeProp.contextVersion}</span>
364	                </div>
365	              ) : (
366	                <div className="flex items-center justify-between">
367	                  <span>context.md</span>
368	                  <span className="font-mono text-muted-foreground/60">—</span>
369	                </div>
370	              )}
371	              <div className="mt-1 flex items-center justify-between">
372	                <span>Hermes</span>
373	                <span className="font-mono text-emerald-500">online</span>
374	              </div>
375	            </div>
376	          )}
377	        </div>
378	      </aside>
379	
380	      {/* Auto-Solve Confirmation Dialog */}
381	      {showAutoSolveConfirm && (
382	        <div
383	          className="fixed inset-0 z-50 flex items-center justify-center bg-black/50"
384	          role="dialog"
385	          aria-modal="true"
386	          aria-labelledby="auto-solve-dialog-title"
387	          onClick={() => setShowAutoSolveConfirm(false)}
388	          onKeyDown={(e) => { if (e.key === "Escape") setShowAutoSolveConfirm(false); }}
389	          tabIndex={-1}
390	        >
391	          <div
392	            className="mx-4 w-full max-w-sm rounded-xl border bg-background p-6 shadow-2xl"
393	            onClick={(e) => e.stopPropagation()}
394	          >
395	            <div className="mb-1 flex items-center gap-2">
396	              <Zap className="h-5 w-5 text-emerald-500" />
397	              <h2 id="auto-solve-dialog-title" className="text-base font-semibold">Activate Agent Auto-Solve?</h2>
398	            </div>
399	            <p className="mb-2 text-sm text-muted-foreground">
400	              Hermes will autonomously process <strong>all open tickets</strong> one by one, in priority order.
401	            </p>
402	            <ul className="mb-5 space-y-1 text-sm text-muted-foreground">
403	              <li className="flex items-start gap-2">
404	                <span className="mt-0.5 h-1.5 w-1.5 shrink-0 rounded-full bg-emerald-500" />
405	                Write actions (emails, responses, reports) auto-confirm after a brief delay
406	              </li>
407	              <li className="flex items-start gap-2">
408	                <span className="mt-0.5 h-1.5 w-1.5 shrink-0 rounded-full bg-amber-500" />
409	                Human escalations are <strong>not</strong> auto-confirmed — they stay pending
410	              </li>
411	              <li className="flex items-start gap-2">
412	                <span className="mt-0.5 h-1.5 w-1.5 shrink-0 rounded-full bg-blue-500" />
413	                You can stop the agent at any time — the current ticket will finish
414	              </li>
415	            </ul>
416	            <div className="flex justify-end gap-3">
417	              <button
418	                onClick={() => setShowAutoSolveConfirm(false)}
419	                className="rounded-md px-4 py-2 text-sm font-medium hover:bg-accent"
420	              >
421	                Cancel
422	              </button>
423	              <button
424	                onClick={handleAutoSolveConfirm}
425	                className="flex items-center gap-2 rounded-md bg-emerald-600 px-4 py-2 text-sm font-medium text-white hover:bg-emerald-700 transition-colors"
426	              >
427	                <Zap className="h-3.5 w-3.5" />
428	                Activate Auto-Solve
429	              </button>
430	            </div>
431	          </div>
432	        </div>
433	      )}
434	
435	      {/* Reset Confirmation Dialog */}
436	      {showResetConfirm && (
437	        <div
438	          className="fixed inset-0 z-50 flex items-center justify-center bg-black/50"
439	          role="dialog"
440	          aria-modal="true"
441	          aria-labelledby="reset-dialog-title"
442	          onClick={() => setShowResetConfirm(false)}
443	          onKeyDown={(e) => { if (e.key === "Escape") setShowResetConfirm(false); }}
444	          // eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions
445	          tabIndex={-1}
446	        >
447	          {/* stopPropagation prevents backdrop click from reaching the inner card */}
448	          <div
449	            className="mx-4 w-full max-w-sm rounded-xl border bg-background p-6 shadow-2xl"
450	            onClick={(e) => e.stopPropagation()}
451	          >
452	            <div className="mb-1 flex items-center gap-2">
453	              <RotateCcw className="h-5 w-5 text-destructive" />
454	              <h2 id="reset-dialog-title" className="text-base font-semibold">Demo zurücksetzen?</h2>
455	            </div>
456	            <p className="mb-5 text-sm text-muted-foreground">
457	              Alle Tickets, Vorschläge, Kontextänderungen und Protokolle werden gelöscht und
458	              durch den Demo-Ausgangszustand ersetzt. <strong>Diese Aktion kann nicht rückgängig gemacht werden.</strong>
459	            </p>
460	            <div className="flex justify-end gap-3">
461	              <button
462	                onClick={() => setShowResetConfirm(false)}
463	                className="rounded-md px-4 py-2 text-sm font-medium hover:bg-accent"
464	              >
465	                Abbrechen
466	              </button>
467	              <button
468	                onClick={handleReset}
469	                className="rounded-md bg-destructive px-4 py-2 text-sm font-medium text-destructive-foreground hover:bg-destructive/90 transition-colors"
470	              >
471	                Ja, zurücksetzen
472	              </button>
473	            </div>
474	          </div>
475	        </div>
476	      )}
477	    </>
478	  );
479	}
480	
481	function Zone({ label, children }: { label: string; children: React.ReactNode }) {
482	  return (
483	    <div className="mb-4">
484	      <div className="mb-1 px-2 text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">{label}</div>
485	      <div className="flex flex-col gap-0.5">{children}</div>
486	    </div>
487	  );
488	}
489	
490	function Item({
491	  href, icon: Icon, active, children,
492	}: { href: string; icon: React.ComponentType<{ className?: string }>; active?: boolean; children: React.ReactNode }) {
493	  return (
494	    <Link
495	      href={href}
496	      className={cn(
497	        "flex items-center gap-2 rounded-md px-2 py-1.5 text-sm hover:bg-accent",
498	        active && "bg-accent font-medium"
499	      )}
500	    >
501	      <Icon className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
502	      <span>{children}</span>
503	    </Link>
504	  );
505	}
