1	"use client";
2	
3	/**
4	 * overview-client.tsx  (Sprint 3, s3-f3)
5	 *
6	 * Client-side interactive layer for the overview page.
7	 * Polls the tickets + properties APIs every 2 seconds when the auto-solve
8	 * queue is active so the pipeline view updates without a page refresh.
9	 *
10	 * Also subscribes to the global bus for ticket-changed events (manual actions
11	 * trigger an immediate re-fetch without waiting for the next poll cycle).
12	 *
13	 * The "currently processing" ticket gets a pulsing ring indicator.
14	 */
15	
16	import { useEffect, useRef, useState } from "react";
17	import Link from "next/link";
18	import { cn } from "@repo/ui/lib/utils";
19	import { Card, CardContent } from "@repo/ui/components/card";
20	import { Badge } from "@repo/ui/components/badge";
21	import { RiskBadge } from "@/components/badges";
22	import { PageHeader } from "@/components/page-header";
23	import { Button } from "@repo/ui/components/button";
24	import { AlertTriangle, ArrowRight, Mail, Phone } from "lucide-react";
25	import { api } from "@/lib/api";
26	import { pipelineStages } from "@/lib/pipeline";
27	import { timeAgo, formatEur } from "@/lib/utils";
28	import { subscribe } from "@/lib/bus";
29	import { useAutoSolve } from "@/lib/auto-solve-context";
30	import type { Ticket, Property } from "@/lib/types";
31	
32	const POLL_INTERVAL_ACTIVE = 2000;   // 2s when agent is running
33	const POLL_INTERVAL_IDLE   = 10000;  // 10s otherwise
34	
35	export function OverviewClient({
36	  initialTickets,
37	  initialProperties,
38	}: {
39	  initialTickets: Ticket[];
40	  initialProperties: Property[];
41	}) {
42	  const [tickets, setTickets] = useState<Ticket[]>(initialTickets);
43	  const [properties, setProperties] = useState<Property[]>(initialProperties);
44	  const { autoSolve, queueStatus } = useAutoSolve();
45	  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
46	
47	  const refresh = async () => {
48	    try {
49	      const [t, p] = await Promise.all([
50	        api.tickets.list(),
51	        api.properties.list(),
52	      ]);
53	      setTickets(t);
54	      setProperties(p);
55	    } catch {
56	      // silently ignore — stale data is better than crashing
57	    }
58	  };
59	
60	  // Polling loop
61	  useEffect(() => {
62	    let cancelled = false;
63	    const interval = autoSolve ? POLL_INTERVAL_ACTIVE : POLL_INTERVAL_IDLE;
64	
65	    const schedule = () => {
66	      timerRef.current = setTimeout(async () => {
67	        if (cancelled) return;
68	        await refresh();
69	        if (!cancelled) schedule();
70	      }, interval);
71	    };
72	
73	    schedule();
74	    return () => {
75	      cancelled = true;
76	      if (timerRef.current) clearTimeout(timerRef.current);
77	    };
78	  }, [autoSolve]);
79	
80	  // Also re-fetch immediately on bus events (e.g. manual approvals)
81	  useEffect(() => {
82	    const unsub = subscribe((event) => {
83	      if (event.kind === "ticket-changed" || event.kind === "queue-tick") {
84	        refresh();
85	      }
86	    });
87	    return unsub;
88	  }, []);
89	
90	  const unsolved = tickets.filter((t) => !["resolved", "rejected"].includes(t.status));
91	  const proposed = tickets.filter((t) => t.status === "proposed");
92	  const completed = tickets.filter((t) => t.status === "completed");
93	  const resolved7d = tickets.filter((t) => t.status === "resolved").length;
94	
95	  const kpis: Array<{ label: string; value: number; accent?: "amber" | "emerald" }> = [
96	    { label: "Awaiting your approval", value: proposed.length, accent: "amber" },
97	    { label: "In flight", value: unsolved.filter((t) => ["awaiting_vendor", "scheduled", "in_progress"].includes(t.status)).length },
98	    { label: "Memory writes pending", value: completed.length, accent: "emerald" },
99	    { label: "Resolved", value: resolved7d },
100	  ];
101	
102	  const currentlyProcessing = queueStatus.currentTicketId;
103	
104	  return (
105	    <div>
106	      <PageHeader
107	        title="Overview"
108	        subtitle="Pipeline across all properties"
109	        actions={
110	          <div className="flex items-center gap-2">
111	            {autoSolve && (
112	              <div className="flex items-center gap-1.5 rounded-full bg-emerald-500/15 px-3 py-1 text-xs font-medium text-emerald-600 dark:text-emerald-400">
113	                <span className="h-1.5 w-1.5 rounded-full bg-emerald-500 animate-pulse" />
114	                Agent running · {queueStatus.remainingCount} tickets left
115	              </div>
116	            )}
117	            <Button variant="outline" size="sm">
118	              Last 24h
119	            </Button>
120	          </div>
121	        }
122	      />
123	
124	      <div className="space-y-6 p-8">
125	        {/* KPI row */}
126	        <div className="grid grid-cols-4 gap-4">
127	          {kpis.map((k) => (
128	            <Card key={k.label} className="transition-all duration-300">
129	              <CardContent className="p-5">
130	                <div className="text-xs uppercase tracking-wider text-muted-foreground">{k.label}</div>
131	                <div
132	                  className={cn(
133	                    "mt-2 text-3xl font-semibold tabular-nums transition-all duration-500",
134	                    k.accent === "amber" ? "text-amber-700" : k.accent === "emerald" ? "text-emerald-700" : ""
135	                  )}
136	                >
137	                  {k.value}
138	                </div>
139	              </CardContent>
140	            </Card>
141	          ))}
142	        </div>
143	
144	        {/* Pipeline */}
145	        <div>
146	          <h2 className="mb-3 text-sm font-semibold uppercase tracking-wider text-muted-foreground">Pipeline</h2>
147	          <div className="grid grid-cols-6 gap-3">
148	            {pipelineStages.map((stage) => {
149	              const stageTickets = tickets.filter((t) => t.status === stage.id);
150	              return (
151	                <div key={stage.id} className="rounded-lg border bg-background p-3 transition-all duration-200">
152	                  <div className="mb-2 flex items-center justify-between">
153	                    <div className="text-xs font-medium">{stage.label}</div>
154	                    <span className="rounded bg-muted px-1.5 text-[11px] font-mono transition-all duration-300">
155	                      {stageTickets.length}
156	                    </span>
157	                  </div>
158	                  <p className="mb-3 text-[11px] leading-snug text-muted-foreground">{stage.description}</p>
159	                  <div className="space-y-2">
160	                    {stageTickets.map((t) => {
161	                      const prop = properties.find((p) => p.id === t.propertyId);
162	                      const isProcessing = t.id === currentlyProcessing;
163	                      return (
164	                        <Link
165	                          key={t.id}
166	                          href={`/ticket/${t.id}`}
167	                          className={cn(
168	                            "block rounded border bg-card p-2 transition-all duration-200 hover:border-foreground/40",
169	                            isProcessing && "ring-2 ring-emerald-500 ring-offset-1 animate-pulse border-emerald-500/50"
170	                          )}
171	                        >
172	                          <div className="flex items-center justify-between text-[10px] text-muted-foreground">
173	                            <span className="font-mono">{t.num}</span>
174	                            <RiskBadge risk={t.risk} />
175	                          </div>
176	                          <div className="mt-1 line-clamp-2 text-xs font-medium">{t.subject}</div>
177	                          <div className="mt-1 text-[10px] text-muted-foreground">{prop?.name}</div>
178	                          {isProcessing && (
179	                            <div className="mt-1 flex items-center gap-1 text-[10px] text-emerald-600 dark:text-emerald-400">
180	                              <span className="h-1.5 w-1.5 rounded-full bg-emerald-500 animate-ping" />
181	                              Agent processing…
182	                            </div>
183	                          )}
184	                        </Link>
185	                      );
186	                    })}
187	                  </div>
188	                </div>
189	              );
190	            })}
191	          </div>
192	        </div>
193	
194	        {/* Awaiting approval — call to action */}
195	        {proposed.length > 0 && (
196	          <Card className="border-amber-500/30 bg-amber-500/5">
197	            <CardContent className="p-5">
198	              <div className="mb-3 flex items-center gap-2">
199	                <AlertTriangle className="h-4 w-4 text-amber-700" />
200	                <h3 className="text-sm font-semibold">Awaiting your approval ({proposed.length})</h3>
201	              </div>
202	              <div className="space-y-2">
203	                {proposed.map((t) => {
204	                  const prop = properties.find((p) => p.id === t.propertyId);
205	                  return (
206	                    <Link
207	                      key={t.id}
208	                      href={`/ticket/${t.id}`}
209	                      className="flex items-center justify-between rounded-md border bg-background p-3 hover:border-foreground/40"
210	                    >
211	                      <div className="flex min-w-0 items-center gap-3">
212	                        {t.source === "voice" ? (
213	                          <Phone className="h-3.5 w-3.5 text-muted-foreground" />
214	                        ) : (
215	                          <Mail className="h-3.5 w-3.5 text-muted-foreground" />
216	                        )}
217	                        <div className="min-w-0">
218	                          <div className="flex items-center gap-2 text-sm font-medium">
219	                            <span className="truncate">{t.subject}</span>
220	                            <RiskBadge risk={t.risk} />
221	                          </div>
222	                          <div className="text-xs text-muted-foreground">
223	                            {prop?.name} · {t.raisedBy} · {timeAgo(t.createdAt)} ago
224	                            {t.proposal && (
225	                              <> · proposes {t.proposal.proposedAction.vendor} · {formatEur(t.proposal.proposedAction.estimateEur)}</>
226	                            )}
227	                          </div>
228	                        </div>
229	                      </div>
230	                      <ArrowRight className="h-4 w-4 text-muted-foreground" />
231	                    </Link>
232	                  );
233	                })}
234	              </div>
235	            </CardContent>
236	          </Card>
237	        )}
238	
239	        {/* Memory writes pending */}
240	        {completed.length > 0 && (
241	          <Card className="border-emerald-500/30 bg-emerald-500/5">
242	            <CardContent className="p-5">
243	              <div className="mb-3">
244	                <h3 className="text-sm font-semibold">Memory writes pending — vendor closed the job</h3>
245	                <p className="text-xs text-muted-foreground">
246	                  Memory is only proposed AFTER work completes — not at dispatch.
247	                </p>
248	              </div>
249	              <div className="space-y-2">
250	                {completed.map((t) => {
251	                  const prop = properties.find((p) => p.id === t.propertyId);
252	                  return (
253	                    <Link
254	                      key={t.id}
255	                      href={`/ticket/${t.id}`}
256	                      className="flex items-center justify-between rounded-md border bg-background p-3 hover:border-foreground/40"
257	                    >
258	                      <div>
259	                        <div className="text-sm font-medium">{t.subject}</div>
260	                        <div className="text-xs text-muted-foreground">
261	                          {prop?.name} · final cost{" "}
262	                          {t.vendorJob && formatEur(t.vendorJob.finalCostEur ?? 0)} · save to v
263	                          {t.memoryProposal?.targetVersion}?
264	                        </div>
265	                      </div>
266	                      <Badge variant="success">memory pending</Badge>
267	                    </Link>
268	                  );
269	                })}
270	              </div>
271	            </CardContent>
272	          </Card>
273	        )}
274	      </div>
275	    </div>
276	  );
277	}
