6	const BASE =
7	  (typeof process !== "undefined" && process.env?.NEXT_PUBLIC_BACKEND_URL) ||
8	  "http://localhost:8000";
9	
10	export interface ApiErrorEnvelope {
11	  error: string;
12	  code: string;
13	  status: number;
14	}
15	
16	export class ApiError extends Error {
17	  readonly code: string;
18	  readonly status: number;
19	  readonly path: string;
20	  constructor(envelope: ApiErrorEnvelope, path: string) {
21	    super(envelope.error);
22	    this.name = "ApiError";
23	    this.code = envelope.code;
24	    this.status = envelope.status;
25	    this.path = path;
26	  }
27	}
28	
29	export type ApiAction =
30	  | "approve" | "reject" | "saveMemory" | "skipMemory"
31	  | "extract" | "chat" | "load";
32	
33	export function friendlyApiError(err: unknown, action?: ApiAction): { title: string; description?: string } {
34	  if (err instanceof ApiError) {
35	    if (err.code === "CONFLICT" && action === "saveMemory") {
36	      return {
37	        title: "Memory write blocked",
38	        description: "Vendor hasn't reported completion yet — we don't write memory until the job closes.",
39	      };
40	    }
41	    if (err.code === "CONFLICT") {
42	      return { title: "Action blocked", description: err.message };
43	    }
44	    if (err.code === "VALIDATION_ERROR") {
45	      return { title: "Invalid request", description: err.message };
46	    }
47	    if (err.code === "UNAUTHORIZED") {
48	      return { title: "Sign-in required", description: err.message };
49	    }
50	    if (err.code === "NOT_FOUND") {
51	      return { title: "Not found", description: err.message };
52	    }
53	    return { title: "Request failed", description: err.message };
54	  }
55	  if (err instanceof DOMException && err.name === "AbortError") {
56	    return { title: "Cancelled" };
57	  }
58	  return {
59	    title: "Unexpected error",
60	    description: err instanceof Error ? err.message : String(err),
61	  };
62	}
63	
64	type FetchInit = Omit<RequestInit, "body"> & {
65	  query?: Record<string, string | number | boolean | undefined | null>;
66	  body?: unknown;
67	};
68	
69	function buildUrl(path: string, query?: FetchInit["query"]): string {
70	  const url = new URL(path.startsWith("http") ? path : `${BASE}${path}`);
71	  if (query) {
72	    for (const [k, v] of Object.entries(query)) {
73	      if (v === undefined || v === null) continue;
74	      url.searchParams.set(k, String(v));
75	    }
76	  }
77	  return url.toString();
78	}
79	
80	async function request<T>(path: string, init: FetchInit = {}): Promise<T> {
81	  const { query, body, headers, ...rest } = init;
82	  const url = buildUrl(path, query);
83	
84	  const res = await fetch(url, {
85	    ...rest,
86	    headers: {
87	      "Accept": "application/json",
88	      ...(body !== undefined ? { "Content-Type": "application/json" } : {}),
89	      ...headers,
90	    },
91	    body: body === undefined ? undefined : JSON.stringify(body),
92	  });
93	
94	  if (!res.ok) {
95	    let envelope: ApiErrorEnvelope = {
96	      error: res.statusText || "Request failed",
97	      code: "HTTP_ERROR",
98	      status: res.status,
99	    };
100	    try {
101	      const parsed = await res.json();
102	      if (parsed && typeof parsed === "object" && "error" in parsed) {
103	        envelope = {
104	          error: String((parsed as ApiErrorEnvelope).error ?? envelope.error),
105	          code: String((parsed as ApiErrorEnvelope).code ?? envelope.code),
106	          status: Number((parsed as ApiErrorEnvelope).status ?? res.status),
107	        };
108	      }
109	    } catch {
110	      /* non-JSON error body */
111	    }
112	    throw new ApiError(envelope, path);
113	  }
114	
115	  if (res.status === 204) return undefined as unknown as T;
116	  return res.json() as Promise<T>;
117	}
