163	// ---------------------------------------------------------------------------
164	// Sprint 2: Agent-run SSE streaming
165	// ---------------------------------------------------------------------------
166	
167	export interface AgentRunHandlers {
168	  onActionCard?: (action: AgentAction) => void;
169	  onActionProposal?: (proposal: Record<string, unknown>) => void;
170	  onDelta?: (text: string) => void;
171	  onDone?: (payload: { runId: string; ticketId: string; turns: number }) => void;
172	  onError?: (err: unknown) => void;
173	  signal?: AbortSignal;
174	}
175	
176	export const agentRun = {
177	  /**
178	   * POST /api/tickets/{id}/agent-run → text/event-stream
179	   * Streams action_card + delta + done events while persisting actions to DB.
180	   */
181	  stream: async (
182	    ticketId: string,
183	    handlers: AgentRunHandlers,
184	    promptHint?: string
185	  ): Promise<void> => {
186	    const url = buildUrl(`/api/tickets/${encodeURIComponent(ticketId)}/agent-run`);
187	    const res = await fetch(url, {
188	      method: "POST",
189	      headers: { "Content-Type": "application/json", "Accept": "text/event-stream" },
190	      body: JSON.stringify(promptHint ? { promptHint } : {}),
191	      signal: handlers.signal,
192	    });
193	
194	    if (!res.ok || !res.body) {
195	      const env: ApiErrorEnvelope = {
196	        error: `Agent run failed (${res.status})`,
197	        code: "HTTP_ERROR",
198	        status: res.status,
199	      };
200	      try {
201	        const parsed = await res.json();
202	        if (parsed && typeof parsed === "object" && "error" in parsed) {
203	          Object.assign(env, parsed);
204	        }
205	      } catch { /* ignore */ }
206	      throw new ApiError(env, `/api/tickets/${ticketId}/agent-run`);
207	    }
208	
209	    const reader = res.body.getReader();
210	    const decoder = new TextDecoder("utf-8");
211	    let buffer = "";
212	
213	    try {
214	      while (true) {
215	        const { value, done } = await reader.read();
216	        if (done) break;
217	        buffer += decoder.decode(value, { stream: true });
218	
219	        let sep: number;
220	        while ((sep = buffer.indexOf("\n\n")) !== -1) {
221	          const frame = buffer.slice(0, sep);
222	          buffer = buffer.slice(sep + 2);
223	          parseAgentRunFrame(frame, handlers);
224	        }
225	      }
226	      if (buffer.trim().length > 0) parseAgentRunFrame(buffer, handlers);
227	    } catch (err) {
228	      handlers.onError?.(err);
229	      throw err;
230	    }
231	  },
232	};
233	
234	function parseAgentRunFrame(frame: string, handlers: AgentRunHandlers): void {
235	  let event = "message";
236	  const dataLines: string[] = [];
237	  for (const line of frame.split("\n")) {
238	    if (line.startsWith("event:")) event = line.slice(6).trim();
239	    else if (line.startsWith("data:")) dataLines.push(line.slice(5).trim());
240	  }
241	  if (dataLines.length === 0) return;
242	  const raw = dataLines.join("\n");
243	  let parsed: any;
244	  try { parsed = JSON.parse(raw); } catch { parsed = {}; }
245	
246	  if (event === "action_card") handlers.onActionCard?.(parsed as AgentAction);
247	  else if (event === "action_proposal") handlers.onActionProposal?.(parsed);
248	  else if (event === "delta") handlers.onDelta?.(parsed.text ?? "");
249	  else if (event === "done") handlers.onDone?.(parsed);
250	  else if (event === "error") handlers.onError?.(parsed);
251	}
