296	/**
297	 * Confirm a proposed agent action by calling the envelope's confirmEndpoint.
298	 * Uses the same request() helper as the rest of the API client — meaning it
299	 * throws ApiError on non-2xx responses and respects NEXT_PUBLIC_BACKEND_URL.
300	 */
301	export function confirmAction(envelope: {
302	  confirmEndpoint: string;
303	  confirmMethod?: string | null;
304	  confirmBody?: Record<string, unknown> | null;
305	}): Promise<unknown> {
306	  return request(envelope.confirmEndpoint, {
