323	
324	export interface QueueFeedHandlers {
325	  onActivity?: (entry: AgentActivityEntry) => void;
326	  onQueueStatus?: (status: QueueStatus) => void;
327	  onQueueStopped?: () => void;
328	  signal?: AbortSignal;
