331	export const agentQueue = {
332	  start: () =>
333	    request<QueueStatus & { started: boolean }>("/api/agent-queue/start", { method: "POST" }),
334	
335	  stop: () =>
336	    request<QueueStatus & { stopped: boolean }>("/api/agent-queue/stop", { method: "POST" }),
337	
338	  status: () =>
339	    request<QueueStatus>("/api/agent-queue/status"),
340	
341	  recentFeed: (limit = 50) =>
342	    request<AgentActivityEntry[]>("/api/agent-queue/feed/recent", { query: { limit } }),
343	
344	  /**
345	   * Connect to the SSE activity feed stream.
346	   * Resolves when the stream ends or the signal is aborted.
347	   */
348	  streamFeed: async (handlers: QueueFeedHandlers): Promise<void> => {
349	    const url = buildUrl("/api/agent-queue/feed/stream");
350	    const res = await fetch(url, {
351	      method: "GET",
352	      headers: { "Accept": "text/event-stream" },
353	      signal: handlers.signal,
354	    });
355	
356	    if (!res.ok || !res.body) return;
