function SpeedButton({
  value,
  current,
  onChange,
  disabled,
}: {
  value: DemoSpeed;
  current: DemoSpeed;
  onChange: (s: DemoSpeed) => void;
  disabled?: boolean;
}) {
  const config = DEMO_SPEED_CONFIGS[value];
